# 常用索引
CITY_BY_ID = {c["id"]: c for c in CityList}
CITY_BY_PINYIN = {(c["pinyin"] or "").lower(): c for c in CityList}
DEFAULT_CITY_ID = 14  # 北京


def get_city(city_id):
    """按 id 取城市，找不到返回 None。"""
    try:
        return CITY_BY_ID.get(int(city_id))
    except (TypeError, ValueError):
        return None


def search_city(keyword):
    """按中文名 / 拼音 / 缩写模糊搜索，供 GUI 城市下拉使用。"""
    kw = (keyword or "").strip().lower()
    if not kw:
        return CityList
    return [c for c in CityList
            if kw in (c["name"] or "").lower()
            or kw in (c["pinyin"] or "").lower()
            or kw in (c["abbr"] or "").lower()]


